        let startCentroid = null;
        let startDistance = 0;
        let startZoom = 1;
        let suppressClick = false;
        let edgePanRaf = 0;
        let edgePanPreviousTime = 0;
        let edgePanOffset = { x: 0, y: 0 };
        let gestureRect = null;
