        cleanups.push(() => sceneGrid.removeEventListener("pointermove", handlePointerMove));
        cleanups.push(() => sceneGrid.removeEventListener("pointerup", handlePointerEnd));
        cleanups.push(() => sceneGrid.removeEventListener("pointercancel", handlePointerEnd));
